package com.spaceagent.platform.runtime.infrastructure.memory;
import com.spaceagent.platform.runtime.domain.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.stereotype.Repository;import java.time.Instant;import java.util.*;
@Repository @ConditionalOnProperty(prefix="platform",name="persistence",havingValue="memory",matchIfMissing=true) public class InMemoryRuntimeGraphSessionRepository implements RuntimeGraphSessionRepository{private final Map<String,RuntimeGraphSession> sessions=new LinkedHashMap<>();private final Map<String,RuntimeGraphCommand> commands=new LinkedHashMap<>();public synchronized void insert(RuntimeGraphSession s){if(sessions.containsKey(s.id())||sessions.values().stream().anyMatch(v->v.agentRunId().equals(s.agentRunId())))throw new IllegalStateException("graph session exists");sessions.put(s.id(),s);}public synchronized Optional<RuntimeGraphSession> findById(String t,String o,String id){return Optional.ofNullable(sessions.get(id)).filter(v->v.tenantId().equals(t)&&v.ownerUserId().equals(o));}public synchronized Optional<RuntimeGraphSession> findByRunId(String t,String o,String run){return sessions.values().stream().filter(v->v.tenantId().equals(t)&&v.ownerUserId().equals(o)&&v.agentRunId().equals(run)).findFirst();}public synchronized boolean update(RuntimeGraphSession s,long rev,GraphSessionState state){var old=sessions.get(s.id());if(old==null||old.revision()!=rev||old.state()!=state)return false;sessions.put(s.id(),s);return true;}public synchronized RuntimeGraphCommand insertCommandIfAbsent(RuntimeGraphCommand c){var key=c.graphSessionId()+":"+c.commandId();var old=commands.putIfAbsent(key,c);if(old!=null&& !old.inputHash().equals(c.inputHash()))throw new IllegalStateException("graph command input conflict");return old==null?c:old;}public synchronized Optional<RuntimeGraphCommand> findCommand(String s,String c){return Optional.ofNullable(commands.get(s+":"+c));}public synchronized boolean updateCommand(RuntimeGraphCommand c,long rev,RuntimeGraphCommand.State state){var key=c.graphSessionId()+":"+c.commandId();var old=commands.get(key);if(old==null||old.revision()!=rev||old.state()!=state)return false;commands.put(key,c);return true;}public synchronized int cleanupCompletedBefore(Instant before){var ids=sessions.values().stream().filter(v->v.state()==GraphSessionState.COMPLETED&&v.updatedAt().isBefore(before)).map(RuntimeGraphSession::id).toList();ids.forEach(sessions::remove);commands.entrySet().removeIf(e->ids.stream().anyMatch(id->e.getKey().startsWith(id+":")));return ids.size();}}
